import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  random,
  Easing,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    // Modified to include weight 900 for "Black" font style
    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map(
        (font) =>
          `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800;900`
      )
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type ScaleAndReachProps = Record<string, any>;

const ScaleAndReach: React.FC<ScaleAndReachProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 8,
  primaryColor = "#C7953D",
  particleColor = "#C7953D",
  particleCount = 200,
  particleSize = 4,
  heroFontSize = 120,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Generate deterministic particles
  const particles = React.useMemo(() => {
    return new Array(particleCount).fill(0).map((_, i) => {
      const seed = i;
      // Random angle and distance
      const angle = random(seed) * Math.PI * 2;
      // Distribute distance to create a volume effect (more in center, spreading out)
      const distance =
        random(seed + 1) * (Math.max(width, height) * 0.8) + 100;
      
      const xEnd = Math.cos(angle) * distance;
      const yEnd = Math.sin(angle) * distance;
      const sizeVariation = random(seed + 2) * 0.5 + 0.5; // 0.5 to 1.0

      return {
        id: i,
        xEnd,
        yEnd,
        sizeVariation,
        delay: random(seed + 3) * 30, // Random start delay up to 30 frames
      };
    });
  }, [particleCount, width, height]);

  // Main Counter Animation
  const counterDuration = 2.5 * fps;
  const counterStart = 20; // Start after ~0.6s
  
  // Easing for the counter number
  const counterProgress = interpolate(
    frame,
    [counterStart, counterStart + counterDuration],
    [0, 1],
    {
      easing: Easing.bezier(0.16, 1, 0.3, 1), // Expo-ish ease out
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  const currentCount = Math.floor(interpolate(counterProgress, [0, 1], [0, 50]));

  // Text Reveal Animation
  const textOpacity = interpolate(
    frame,
    [counterStart + 10, counterStart + 40],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const textTranslateY = interpolate(
    frame,
    [counterStart + 10, counterStart + 40],
    [20, 0],
    {
      easing: Easing.out(Easing.quad),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Global Scale / Camera move effect
  const globalScale = interpolate(
    frame,
    [0, durationInSeconds * fps],
    [1, 1.1],
    { extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Inter",
        overflow: "hidden",
      }}
    >
      {/* 1. Particle Layer */}
      <AbsoluteFill
        style={{
          transform: `scale(${globalScale})`,
          transformOrigin: "center center",
        }}
      >
        {particles.map((p) => {
          // Individual particle animation
          const progress = spring({
            frame: frame - p.delay, // Staggered start
            fps,
            config: {
              damping: 200,
              stiffness: 100,
              mass: 2, // Heavy, slow movement
            },
          });

          // Move from center (0,0 relative) to (xEnd, yEnd)
          // We center the coordinate system later
          const x = interpolate(progress, [0, 1], [0, p.xEnd]);
          const y = interpolate(progress, [0, 1], [0, p.yEnd]);
          
          const opacity = interpolate(
            frame - p.delay,
            [0, 20],
            [0, 0.6], // Max opacity 0.6 for subtle background
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          const scale = interpolate(progress, [0, 1], [0, 1]);

          // Don't render if not started
          if (frame < p.delay) return null;

          return (
            <div
              key={p.id}
              style={{
                position: "absolute",
                left: width / 2,
                top: height / 2,
                width: particleSize * p.sizeVariation,
                height: particleSize * p.sizeVariation,
                borderRadius: "50%",
                backgroundColor: particleColor,
                opacity,
                transform: `translate(${x}px, ${y}px) scale(${scale})`,
              }}
            />
          );
        })}
      </AbsoluteFill>

      {/* 2. Main Content Layer */}
      <AbsoluteFill
        style={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          flexDirection: "column",
          textAlign: "center",
          zIndex: 10,
        }}
      >
        {/* Main Counter Number */}
        <div
          style={{
            fontSize: heroFontSize,
            fontWeight: 900, // Inter Black
            color: primaryColor,
            lineHeight: 1,
            marginBottom: heroFontSize * 0.1,
            opacity: textOpacity,
            transform: `translateY(${textTranslateY}px)`,
            fontFeatureSettings: '"tnum" on, "lnum" on', // Tabular lining nums prevent jitter
          }}
        >
          {currentCount} Deaths
        </div>

        {/* Subtext: per 100,000 workers */}
        <div
          style={{
            fontSize: heroFontSize * 0.45,
            fontWeight: 800,
            color: primaryColor,
            opacity: textOpacity,
            transform: `translateY(${textTranslateY}px)`,
            letterSpacing: "0.02em",
            lineHeight: 1,
            marginBottom: heroFontSize * 0.05,
          }}
        >
          per 100,000 workers
        </div>

        {/* Subtext: a year */}
        <div
          style={{
            fontSize: heroFontSize * 0.28,
            fontWeight: 600,
            color: primaryColor,
            opacity: textOpacity, 
            transform: `translateY(${textTranslateY}px)`,
            letterSpacing: "0.05em",
          }}
        >
          a year
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default ScaleAndReach;